{
  "name": "@etsuya/nano-context-opencode",
  "version": "0.1.2",
  "description": "A nano-context style segmented token meter for the OpenCode V2 TUI sidebar: input / output / cache segments plus a cache hit rate.",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Etsuya233/nano-context-opencode.git"
  },
  "bugs": {
    "url": "https://github.com/Etsuya233/nano-context-opencode/issues"
  },
  "homepage": "https://github.com/Etsuya233/nano-context-opencode#readme",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.ts"
  },
  "files": [
    "index.ts",
    "tui.ts",
    "src",
    "!src/*.test.ts",
    "!src/*.test.tsx",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test src/bar.test.ts",
    "prepublishOnly": "npm run typecheck && npm test"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "sidebar",
    "tokens",
    "context",
    "cache"
  ],
  "dependencies": {
    "@opencode/plugin": ">=2.0.18"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.4.5",
    "@opentui/solid": ">=0.4.5",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.18",
    "@opencode/theme": "^2.0.18",
    "@opentui/core": "^0.5.12",
    "@opentui/solid": "^0.5.12",
    "@types/node": "^24.0.0",
    "solid-js": "^1.9.0",
    "typescript": "^5.7.0"
  }
}
